// Some portions generated by Claude
// @ts-check
const { test, expect } = require('@playwright/test');
const {
    deleteRepository,
    memoryRepositoryConfiguration,
    repositoryPageUrl,
    serverBaseUrl,
    uniqueRepositoryId,
    waitForRoute
} = require('./workbench-test-helpers.js');

// A click on (or next to) a link opens its statement: what the predicate means, and a card for every resource that
// says something about the statement: RDF 1.2 reifiers, classic rdf:Statement reifications and references.
const REPOSITORY_ID = uniqueRepositoryId('graph-statements');
const ALICE = 'http://example.org/statements/alice';
const DATA = `
@prefix ex: <http://example.org/statements/> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
ex:alice rdfs:label "Alice" ; ex:knows ex:bob .
ex:bob rdfs:label "Bob" .
ex:knows rdfs:label "knows" ; rdfs:comment "A person knows another person."@en ; rdfs:domain ex:Person .
ex:alice ex:describes ex:bob .
ex:describes rdfs:label "describes" ; rdfs:comment "وصف العلاقة."@ar--rtl .
<< ex:alice ex:knows ex:bob ~ ex:claim >> rdfs:label "Claim" ; ex:source ex:wiki .
ex:alice ex:knows ex:bob {| ex:since 2001 |} .
ex:stmt a rdf:Statement ; rdf:subject ex:alice ; rdf:predicate ex:knows ; rdf:object ex:bob ; ex:by ex:dave .
ex:carol rdfs:label "Carol" ; ex:believes <<( ex:alice ex:knows ex:bob )>> .
`;

test.beforeAll(async ({ request }) => {
    const repositoryUrl = `${serverBaseUrl()}/repositories/${REPOSITORY_ID}`;
    const created = await request.put(repositoryUrl, {
        headers: { 'Content-Type': 'text/turtle' },
        data: memoryRepositoryConfiguration(REPOSITORY_ID, 'Graph statements')
    });
    expect([200, 201, 204]).toContain(created.status());
    const loaded = await request.post(`${repositoryUrl}/statements`, {
        headers: { 'Content-Type': 'text/turtle' },
        data: DATA
    });
    expect([200, 204]).toContain(loaded.status());
});

test.afterAll(async ({ request }) => {
    await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

/** A point `offset` pixels beside the middle of the edge (0: on the line itself). */
async function besideEdge(page, title, offset = 4) {
    return page.evaluate(([prefix, offset]) => {
        const edge = [...document.querySelectorAll('.graph-explorer .edge')]
            .find((candidate) => candidate.querySelector('title')?.textContent?.startsWith(prefix));
        const path = edge.querySelector('path');
        const length = path.getTotalLength();
        const middle = path.getPointAtLength(length / 2);
        const ahead = path.getPointAtLength(length / 2 + 1);
        const matrix = path.getScreenCTM();
        const screen = (point) => new DOMPoint(point.x, point.y).matrixTransform(matrix);
        const [a, b] = [screen(middle), screen(ahead)];
        const norm = Math.hypot(b.x - a.x, b.y - a.y) || 1;
        return { x: a.x - ((b.y - a.y) / norm) * offset, y: a.y + ((b.x - a.x) / norm) * offset };
    }, [title, offset]);
}

async function openAliceGraph(page) {
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.goto(`${repositoryPageUrl(REPOSITORY_ID, 'explore')}?resource=${encodeURIComponent(`<${ALICE}>`)}`);
    await waitForRoute(page, 'explore');
    await page.getByRole('button', { name: 'Add to graph' }).first().click();
    await page.getByRole('link', { name: 'Open graph' }).click();
    await waitForRoute(page, 'graph');
    const explorer = page.locator('.graph-explorer');
    await expect(explorer.locator('.graph-node').filter({ has: page.locator('text', { hasText: 'Bob' }) })).toBeAttached({ timeout: 30000 });
    await page.waitForTimeout(1500); // the layout settles
    return explorer;
}

test('a click beside a link opens its statement, with the predicate and what is said about the statement', async ({ page }) => {
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.goto(`${repositoryPageUrl(REPOSITORY_ID, 'explore')}?resource=${encodeURIComponent(`<${ALICE}>`)}`);
    await waitForRoute(page, 'explore');
    await page.getByRole('button', { name: 'Add to graph' }).first().click();
    await page.getByRole('link', { name: 'Open graph' }).click();
    await waitForRoute(page, 'graph');
    const explorer = page.locator('.graph-explorer');
    const node = (label) => explorer.locator('.graph-node').filter({ has: page.locator('text', { hasText: label }) }).first();
    await expect(node('Bob')).toBeAttached({ timeout: 30000 });
    await expect(node('Carol')).toHaveCount(0);
    await page.waitForTimeout(1500); // the layout settles

    const point = await besideEdge(page, 'Alice — knows → Bob');
    await page.mouse.move(point.x, point.y);
    await expect(explorer.locator('.graph-canvas')).toHaveClass(/has-edge-hover/);
    await page.mouse.click(point.x, point.y);

    const card = explorer.locator('.statement-details');
    await expect(card.locator('h3')).toHaveText('knows');
    await expect(card.locator('.statement-details-triple')).toHaveText('Alice→Bob');
    await expect(card.locator('.statement-details-description')).toHaveText('A person knows another person.');
    await expect(card.locator('.node-details-row', { hasText: 'Domain' })).toContainText('Person');
    await expect(card.locator('.node-details-row', { hasText: 'Used in' })).toContainText('1 statement');

    const cards = card.locator('.statement-card');
    await expect(cards).toHaveCount(4);
    await expect(cards.nth(0).locator('header')).toContainText('Reifier');
    await expect(card.locator('.statement-card', { hasText: 'Claim' })).toContainText('wiki');
    await expect(card.locator('.statement-card', { hasText: 'Blank node' })).toContainText('2001');
    await expect(card.locator('.statement-card[data-kind="reification"]')).toContainText('dave');
    const reference = card.locator('.statement-card[data-kind="reference"]');
    await expect(reference).toContainText('Carol');
    await expect(reference).toContainText('this statement');

    await reference.getByRole('button', { name: 'Add Carol to the graph' }).click();
    await expect(node('Carol')).toBeAttached({ timeout: 30000 });

    await page.keyboard.press('Escape');
    await expect(card).toHaveCount(0);
});

test('a click on the line of a link, or on its label, opens its statement', async ({ page }) => {
    const explorer = await openAliceGraph(page);
    const card = explorer.locator('.statement-details');

    const onLine = await besideEdge(page, 'Alice — knows → Bob', 0);
    await page.mouse.click(onLine.x, onLine.y);
    await expect(card.locator('h3')).toHaveText('knows');
    await page.keyboard.press('Escape');
    await expect(card).toHaveCount(0);

    // Labels show for the links of the hovered node; a click on one opens that link's statement.
    await explorer.locator('.graph-node').filter({ has: page.locator('text', { hasText: 'Alice' }) }).first().hover();
    const label = explorer.locator('.edge.show-label', { has: page.locator('title', { hasText: 'Alice — knows → Bob' }) }).locator('text');
    await label.click();
    await expect(card.locator('h3')).toHaveText('knows');
});

test('directional predicate descriptions keep their language and base direction', async ({ page }) => {
    const explorer = await openAliceGraph(page);
    const point = await besideEdge(page, 'Alice — describes → Bob');
    await page.mouse.click(point.x, point.y);

    const description = explorer.locator('.statement-details-description');
    await expect(description).toHaveText('وصف العلاقة.@ar--rtl');
    await expect(description).toHaveAttribute('dir', 'rtl');
    await expect(description.locator('small')).toHaveText('@ar--rtl');
});
